BEGIN;
CREATE TABLE enterprise_workflow.catalog_admins(enterprise_id uuid NOT NULL,subject text NOT NULL,enabled boolean NOT NULL DEFAULT true,PRIMARY KEY(enterprise_id,subject),FOREIGN KEY(enterprise_id,subject) REFERENCES enterprise_workflow.accounts(enterprise_id,subject));
CREATE TABLE enterprise_workflow.catalog_entities(enterprise_id uuid NOT NULL,id uuid NOT NULL,kind text NOT NULL CHECK(kind IN('brand','shop','product','sku')),version integer NOT NULL CHECK(version>0),document jsonb NOT NULL,external_key text,PRIMARY KEY(enterprise_id,id),UNIQUE(enterprise_id,kind,external_key));
CREATE TABLE enterprise_workflow.catalog_commands(enterprise_id uuid NOT NULL,id uuid NOT NULL,actor text NOT NULL,reason text NOT NULL,fingerprint text NOT NULL,result jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(enterprise_id,id));
CREATE TABLE enterprise_workflow.catalog_revisions(enterprise_id uuid NOT NULL,id uuid NOT NULL,version integer NOT NULL,kind text NOT NULL,document jsonb NOT NULL,command_id uuid NOT NULL,PRIMARY KEY(enterprise_id,id,version),FOREIGN KEY(enterprise_id,id) REFERENCES enterprise_workflow.catalog_entities(enterprise_id,id),FOREIGN KEY(enterprise_id,command_id) REFERENCES enterprise_workflow.catalog_commands(enterprise_id,id));
CREATE INDEX catalog_kind ON enterprise_workflow.catalog_entities(enterprise_id,kind,id);
ALTER TABLE enterprise_workflow.runtime_installation ADD COLUMN availability_enabled boolean NOT NULL DEFAULT false;
UPDATE enterprise_workflow.runtime_installation SET availability_enabled=(minimum_reader>=17);
INSERT INTO enterprise_workflow.schema_version VALUES(19);
COMMIT;
